select t1.* from ( select (@i :=@i + 1) AS row_num, gc.company_id, gc.gld_cashflow_id, gc.period_name, gc.start_date, gc.end_date, gc.start_date||'__'||gc.end_date start_end_Date, gc.days, gc.finance_income, gc.source_type, gc.cf_item, (select hci.description from hls_cashflow_item hci where hci.cf_item = gc.cf_item) cf_item_desc, gc.finance_income_includ, gc.finance_income_vat, cc.vat_rate*100||'%' tax_type_rate, gc.post_flag, (select tt.MEANING from sys_code_value_b_v tt where tt.CODE = 'CLD.POST_FLAG' AND tt.code_value = nvl(gc.post_flag,'N')) post_flag_desc, gc.vat_income, cc.contract_number, cc.contract_name, (select hbm.bp_name from hls_bp_master hbm where hbm.bp_id = cc.tenant_id) bp_name, gc.finance_income_id from gld_contract_finance_income gc,con_contract cc,con_contract_cashflow ccc where gc.contract_id = cc.contract_id,(SELECT @i := 0) AS row_seq and cc.data_class = 'NORMAL' and ccc.cashflow_id = gc.gld_cashflow_id ) t1
