SELECT gp.* FROM gld_period gp, gld_set_of_books gsof, gld_financial_attribute gfa WHERE gfa.COMPANY_ID = #{companyId} AND gfa.SET_OF_BOOKS_ID = gsof.SET_OF_BOOKS_ID AND gsof.PERIOD_SET_ID = gp.PERIOD_SET_ID AND gp.PERIOD_NAME IN ( SELECT gps.PERIOD_NAME FROM gld_period_status gps WHERE gps. STATUS = 'OPEN' AND gps.company_id = #{companyId} )
AND gp.PERIOD_NAME = #{periodName}
ORDER BY PERIOD_NAME

select v.* from (select t.finance_income_id, t.company_id, t.cf_item, t.contract_id, t.gld_cashflow_id, t.period_name, to_date(t.start_date,'YYYY-MM-DD') start_date, to_date(t.end_date,'YYYY-MM-DD') end_date, t.days, t.finance_income, t.source_type, t.source_id, t.quotation_id, t.post_flag, t.vat_income, t.finance_income_includ, t.finance_income_vat, (select hls.bp_name from hls_bp_master hls where c.tenant_id = hls.bp_id) bp_name, (select p.project_name from prj_project p,prj_project vc where vc.project_id = c.project_id and p.project_id = vc.ref_project_id) project_name, (select vc.contract_number from prj_project vc where vc.project_id = c.project_id) vc_contract_number, (select vc.contract_name from prj_project vc where vc.project_id = c.project_id) vc_contract_name, c.contract_number, (select vc.finance_amount from prj_project vc where vc.project_id = c.project_id) finance_amount, (select to_date(pq.lease_start_date,'YYYY-MM-DD') from prj_quotation pq where pq.quotation_id = c.quotation_id) incept_date, ccc.times, c.vat_rate, nvl(c.cease_interesst_flag,'N') cease_interesst_flag, (case when nvl(c.cease_interesst_flag,'N') = 'N' then '否' else '是' end) cease_interesst_flag_n, ccc.amortization_method, (select s.MEANING from sys_code_value_b_v s where s.code = 'EXP.AMORTIZATION_METHOD' and s.code_value = ccc.amortization_method) amortization_method_n, (select fc.company_full_name from fnd_company fc where fc.company_id = t.company_id) company_full_name, nvl(t.pre_post_flag,'N') as pre_post_flag
from gld_contract_finance_income t left join con_contract_cashflow ccc on t.gld_cashflow_id = ccc.cashflow_id left join con_contract c on c.contract_id = t.contract_id order by t.period_name desc) v
