mapper.delete:
DELETE
FROM gld_contract_finance_income t
WHERE t.contract_id = #{contractId}
  AND t.cf_item IN (1, 10)
  AND t.post_flag = #{postFlag}

DELETE
FROM gld_contract_finance_income t
WHERE t.contract_id = #{contractId}
  AND t.cf_item = #{cfItem}
  AND t.post_flag = #{postFlag}

mapper.insert:
insert into gld_contract_finance_income ( finance_income_id, company_id, contract_id, gld_cashflow_id, period_name, start_date, end_date, days, finance_income, source_type, source_id, quotation_id, post_flag, cf_item, object_version_number, request_id, program_id, created_by, creation_date, last_updated_by, last_update_date, last_update_login ) SELECT gld_contract_finance_income_s.nextval id, t.* FROM (
SELECT #{item.companyId} company_id, #{item.contractId} contract_id, #{item.gldCashflowId} gld_cashflow_id, #{item.periodName} period_name, #{item.startDate} start_date, #{item.endDate} end_date, #{item.days} days, #{item.financeIncome} finance_income, #{item.sourceType} source_type, #{item.sourceId} source_id, #{item.quotationId} quotation_id, #{item.postFlag} post_flag, #{item.cfItem} cf_item, 1 object_version_number, 1 request_id, 1 program_id, 1 created_by, sysdate creation_date, 1 last_updated_by, sysdate last_update_date, 1 last_update_login from dual
)t

