select v.* from (select t.finance_income_id, t.company_id, t.cf_item, t.contract_id, t.gld_cashflow_id, t.period_name, to_date(t.start_date,'YYYY-MM-DD') start_date, to_date(t.end_date,'YYYY-MM-DD') end_date, t.days, t.finance_income, t.source_type, t.source_id, t.quotation_id, t.post_flag, t.vat_income, ccc.due_amount, (select last_day(t.end_date) from dual) amortization_date, t.finance_income_includ, t.finance_income_vat, (select hls.bp_name from hls_bp_master hls where c.tenant_id = hls.bp_id) bp_name, (select p.project_name from prj_project p,prj_project vc where vc.project_id = c.project_id and p.project_id = vc.ref_project_id) project_name, (select vc.contract_number from prj_project vc where vc.project_id = c.project_id) vc_contract_number, (select vc.contract_name from prj_project vc where vc.project_id = c.project_id) vc_contract_name, c.contract_number, (select vc.finance_amount from prj_project vc where vc.project_id = c.project_id) finance_amount, (select to_date(pq.lease_start_date,'YYYY-MM-DD') from prj_quotation pq where pq.quotation_id = c.quotation_id) incept_date, --to_date(to_char(c.incept_date,'yyyy-mm-dd'),'yyyy-mm-dd') incept_date, ccc.times, c.vat_rate, /*round((t.finance_income * (1 + c.vat_rate)), 2) due_finance_income, (round((t.finance_income * (1 + c.vat_rate)), 2) - t.finance_income) vat_finance_income,*/ nvl(c.cease_interesst_flag,'N') cease_interesst_flag, (case when nvl(c.cease_interesst_flag,'N') = 'N' then '否' else '是' end) cease_interesst_flag_n, ccc.amortization_method, (select s.MEANING from sys_code_value_b_v s where s.code = 'EXP.AMORTIZATION_METHOD' and s.code_value = ccc.amortization_method) amortization_method_n, (select fc.company_full_name from fnd_company fc where fc.company_id = t.company_id) company_full_name, nvl(t.pre_post_flag,'N') as pre_post_flag
from gld_contract_finance_income t left join con_contract_cashflow ccc on t.gld_cashflow_id = ccc.cashflow_id left join con_contract c on c.contract_id = t.contract_id) v
1=1 and v.contract_id = #{contractId}
and v.gld_cashflow_id = #{gldCashflowId}
and v.cf_item =#{cfItem}
order by v.start_date asc

select t.*, last_day(to_date(t.end_date,'YYYY-MM-DD')) amortization_date from (select gcf.contract_id, gcf.period_name, nvl(sum(gcf.finance_income),0) finance_income, gcf.cf_item, max(gcf.days) days, min(gcf.start_date) start_date, max(gcf.end_date) end_date, max(gcf.POST_FLAG) POST_FLAG from gld_contract_finance_income gcf
gcf.contract_id = #{contractId} and gcf.cf_item = #{cfItem}
group by gcf.contract_id, gcf.period_name, gcf.cf_item) t order by t.start_date asc

SELECT v.* FROM ( SELECT t.finance_income_id, c.company_id, t.cf_item, t.contract_id, t.gld_cashflow_id, t.period_name, t.start_date, t.end_date, t.days, t.finance_income, t.source_type, t.source_id, t.quotation_id, t.post_flag, t.vat_income, t.finance_income_includ, t.finance_income_vat, c.lease_end_date, ( SELECT hls.bp_name FROM hls_bp_master hls WHERE c.tenant_id = hls.bp_id ) bp_name, ( SELECT p.project_name FROM prj_project p, prj_project vc WHERE vc.project_id = c.project_id AND p.project_id = vc.ref_project_id ) project_name,
c.project_id, ( SELECT vc.contract_number FROM prj_project vc WHERE vc.project_id = c.project_id ) vc_contract_number, ( SELECT vc.contract_name FROM prj_project vc WHERE vc.project_id = c.project_id ) vc_contract_name, c.contract_number, ( select q.finance_amount from prj_quotation q where q.quotation_id = c.quotation_id /*and q.data_class = 'CONTRACT_CONFIRM' and SOURCE_DOCUMENT_CATEGORY = 'CONTRACT_CONFIRM'*/ ) finance_amount, ( SELECT pq.lease_start_date FROM prj_quotation pq WHERE pq.quotation_id = c.quotation_id ) incept_date, ccc.times, c.vat_rate, nvl( c.cease_interesst_flag, 'N' ) cease_interesst_flag, ( CASE WHEN nvl( c.cease_interesst_flag, 'N' ) = 'N' THEN '否' ELSE '是' END ) cease_interesst_flag_n, ( SELECT fc.company_full_name FROM fnd_company fc WHERE fc.company_id = c.company_id ) company_full_name, nvl( t.pre_post_flag, 'N' ) AS pre_post_flag, ( SELECT pq.lease_account_date FROM prj_quotation pq WHERE pq.quotation_id = c.quotation_id ) lease_account_date FROM gld_contract_finance_income t LEFT JOIN gld_contract_cashflow ccc ON t.gld_cashflow_id = ccc.gld_cashflow_id LEFT JOIN con_contract c ON c.contract_id = t.contract_id ORDER BY t.period_name DESC ) v
